const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Santa Monica coastal area
  const santaMonica = ee.Geometry.Point([-118.5, 34.0]);
  const coastalRegion = santaMonica.buffer(5000); // 5km buffer for coastal waters

  const targetDate = '2015-10-10';
  const dateRange = 3; // days before/after

  console.log('Analyzing algae bloom for Santa Monica coast, Oct 10, 2015...');

  // Try Sentinel-2
  let collection = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(coastalRegion)
    .filterDate(ee.Date(targetDate).advance(-dateRange, 'day'), 
                ee.Date(targetDate).advance(dateRange, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let collectionSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // Fallback to Landsat 8 if no Sentinel-2
  if (collectionSize === 0) {
    console.log('Trying Landsat 8...');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(coastalRegion)
      .filterDate(ee.Date(targetDate).advance(-dateRange, 'day'), 
                  ee.Date(targetDate).advance(dateRange, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    collectionSize = collection.size().getInfo();
    console.log(`Landsat 8 images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('No images available for the date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get the image closest to target date
  const image = collection.sort('system:time_start').first();
  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  console.log(`Using image from: ${imageDate}`);

  // Determine if Sentinel-2 or Landsat
  const isSentinel = collection.first().bandNames().contains('B2').getInfo();

  let processedImage;
  if (isSentinel) {
    // Sentinel-2: Simple cloud mask and calculate NDVI
    const cloudMask = image.select('QA60').eq(0);
    processedImage = image.updateMask(cloudMask);

    // Calculate NDVI (NIR-Red)/(NIR+Red) - B8 and B4
    processedImage = processedImage.normalizedDifference(['B8', 'B4']).rename('NDVI');
  } else {
    // Landsat 8: Apply scaling and cloud mask
    const cloudMask = image.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0);
    const scaled = image.select(['SR_B[2-5]', 'SR_B7']).multiply(0.0000275).add(-0.2);
    processedImage = scaled.updateMask(cloudMask);

    // Calculate NDVI (B5-B4)/(B5+B4)
    processedImage = processedImage.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  }

  // Check valid pixel count
  const pixelCount = processedImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: coastalRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid water pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean NDVI over coastal waters
  const meanNDVI = processedImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: coastalRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Mean NDVI: ${meanNDVI !== null ? meanNDVI.toFixed(3) : 'null'}`);

  if (meanNDVI === null || isNaN(meanNDVI)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for algae bloom indicators
  // Water typically has negative NDVI
  // Algae blooms show positive NDVI (0.1 to 0.3 range)
  if (meanNDVI > 0.05) {
    console.log('Positive NDVI indicates algae bloom visible.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Normal water signature, no algae bloom detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
